package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.nio.file.*;
import java.lang.management.*;
import javax.management.*;
import java.util.concurrent.*;
import net.minecraft.block.Block;
import net.minecraft.init.Blocks;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.server.MinecraftServer;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.*;
import net.minecraftforge.fml.common.FMLCommonHandler;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.fml.common.eventhandler.*;
import net.minecraftforge.fml.common.gameevent.*;
import zone.moddev.mc.ironagearchitecture.block.*;

/** Standalone server workload coordinator. Native clients build normally while optional workbench jobs run on the server. */
final class MPServerProbe {
    static MPServerProbe INSTANCE;
    final WorldServer world;final MinecraftServer server;final Path root=Paths.get(System.getProperty("iaa.mpRoot"));
    final int expected=Integer.getInteger("iaa.mpClients",1);final boolean spread=Boolean.getBoolean("iaa.mpSpread"),prepare=Boolean.getBoolean("iaa.mpPrepare");
    final Map<Integer,EntityPlayerMP> players=new TreeMap<>();final Map<Integer,MPWireMeter> meters=new TreeMap<>();final Set<Integer> ready=new HashSet<>(),built=new HashSet<>(),verified=new HashSet<>();
    final Map<Integer,Future<MPFingerprint.Result>> fingerprints=new HashMap<>();final Set<Integer> requested=new HashSet<>();
    final List<Map<String,Object>> rows=new ArrayList<>();final List<Double> timings=new ArrayList<>();
    final List<zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk> roofJobs=new ArrayList<>();int reconnectRound;final int reconnects=Integer.getInteger("iaa.mpReconnects",0);final List<MPWireMeter> meterHistory=new ArrayList<>();
    final List<Map<String,Object>> slowTicks=new ArrayList<>();long tickUptime,tickCpu,tickGc;
    long gcMillis(){long total=0;for(GarbageCollectorMXBean bean:ManagementFactory.getGarbageCollectorMXBeans())total+=Math.max(0,bean.getCollectionTime());return total;}
    final ThreadMXBean threads=ManagementFactory.getThreadMXBean();final long serverThread=Thread.currentThread().getId();
    String stage="waiting",measuredStage="waiting",verifyFor="";int ticks,sequence,quiet;long started=System.nanoTime(),stageAt=started,before,phaseCpu,phaseWorker,phaseProcess,phaseIn,phaseOut,phaseRoof;boolean finished;
    static void start(WorldServer world,MinecraftServer server){INSTANCE=new MPServerProbe(world,server);FMLCommonHandler.instance().bus().register(INSTANCE);MinecraftForge.EVENT_BUS.register(INSTANCE);INSTANCE.initialize();}
    MPServerProbe(WorldServer world,MinecraftServer server){this.world=world;this.server=server;}
    void initialize(){world.getGameRules().setOrCreateGameRule("doDaylightCycle","false");world.getGameRules().setOrCreateGameRule("doMobSpawning","false");world.getGameRules().setOrCreateGameRule("doFireTick","false");world.setWorldTime(1000);if(prepare){for(int x=-5;x<=31;x++)for(int z=-5;z<=31;z++)world.getChunkFromChunkCoords(x,z);Set<BlockPos> pads=new HashSet<>();for(int id=0;id<10;id++)for(boolean split:new boolean[]{false,true}){BlockPos p=MPPlan.plot(id,split);for(int x=0;x<8;x++)for(int z=0;z<8;z++)pads.add(p.add(x,0,z));}for(BlockPos p:pads)world.setBlockState(p,Blocks.STONEBRICK.getDefaultState(),2);stage="preparing";}Map<String,Object> data=new LinkedHashMap<>();data.put("ready",true);data.put("headless",System.getProperty("java.awt.headless"));data.put("players",expected);data.put("spread",spread);data.put("sha256",System.getProperty("iaa.runtimeSha256"));MPFiles.write(root.resolve("server-ready.json"),data);System.out.println("IAA_MP_SERVER_READY prepare="+prepare);}
    @SubscribeEvent public void login(PlayerEvent.PlayerLoggedInEvent event){if(!(event.player instanceof EntityPlayerMP))return;EntityPlayerMP player=(EntityPlayerMP)event.player;int id=Integer.parseInt(player.getName().substring(5));if(id<0||id>=expected||players.put(id,player)!=null){fail("Unexpected player "+player.getName());return;}MPWireMeter meter=MPWireMeter.attach(player.connection.netManager);meters.put(id,meter);meterHistory.add(meter);player.setGameType(GameType.CREATIVE);player.capabilities.allowFlying=true;player.capabilities.isFlying=true;player.sendPlayerAbilities();move(id,MPPlan.plot(id,spread),"join");}
    static void status(EntityPlayerMP player,MPNetwork.Status status){if(INSTANCE==null)return;MPServerProbe p=INSTANCE;if(!player.getName().equals(String.format("IAAMP%02d",status.id))){p.fail("Client identity mismatch");return;}if("error".equals(status.kind)){p.fail("Client "+status.id+": "+status.detail);return;}if("roof-approach".equals(status.kind)){zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk desk=p.roofJobs.get(status.id);BlockPos at=desk.getPos();player.connection.setPlayerLocation(at.getX()+.5,at.getY()+1,at.getZ()-4,0,20);return;}if("roof-built".equals(status.kind)){p.move(status.id,MPPlan.plot(status.id,p.spread),"building");return;}if(status.kind.startsWith("roof-")){zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk desk=p.roofJobs.get(status.id);zone.moddev.mc.ironagearchitecture.roof.RoofPlan drawing=zone.moddev.mc.ironagearchitecture.roof.RoofData.get(p.world).drawing(desk.drawing.id);System.out.println("IAA_MP_ROOF_SERVER id="+status.id+" pos="+player.getPosition()+" held="+player.inventory.currentItem+" binding="+zone.moddev.mc.ironagearchitecture.roof.RoofClipboardItem.bound(player.getHeldItemMainhand())+" draft="+drawing.revision+"/"+drawing.base);}System.out.println("IAA_MP_STATUS id="+status.id+" kind="+status.kind+" seq="+status.sequence+" detail="+status.detail);if("ready".equals(status.kind))p.ready.add(status.id);if("built".equals(status.kind)){if(status.operations!=91){p.fail("Wrong operation count "+status.operations);return;}p.built.add(status.id);}if("verified".equals(status.kind)&&status.sequence==p.sequence)p.verified.add(status.id);}
    void command(int id,String kind,BlockPos p,String hash){MPNetwork.CHANNEL.sendTo(new MPNetwork.Command(kind,id,p.getX(),p.getZ(),sequence,hash),players.get(id));}
    void move(int id,BlockPos plot,String phase){EntityPlayerMP p=players.get(id);net.minecraft.util.math.Vec3d at=MPPlan.position(plot,phase.equals("building"),id);p.connection.setPlayerLocation(at.xCoord,at.yCoord,at.zCoord,135,20);command(id,"move:"+phase,plot,"");}
    boolean pending(){for(zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk d:roofJobs)if(d.active)return true;if(SmartChunkWork.pending(world)||SmartCobEvents.pending(world)||SmartWallEvents.pending(world)||SmartThatchEvents.pending(world)||SmartThatchEvents.retrying(world))return true;for(EntityPlayerMP p:players.values())if(zone.moddev.mc.ironagearchitecture.SmartCobNetwork.pending(p)||zone.moddev.mc.ironagearchitecture.roof.RoofNetwork.pending(p))return true;return false;}
    long wire(boolean incoming){long n=0;for(MPWireMeter meter:meterHistory)n+=(incoming?meter.inbound:meter.outbound).get();return n;}
    long workerCpu(){long n=0;for(long id:threads.getAllThreadIds()){ThreadInfo info=threads.getThreadInfo(id);if(info!=null&&info.getThreadName().equals("Architecture shape worker")){long value=threads.getThreadCpuTime(id);if(value>0)n+=value;}}return n;}
    long processCpu(){
        // Read the same counter through JMX without linking to a JRE-restricted type.
        try{return (Long)ManagementFactory.getPlatformMBeanServer().getAttribute(
                new ObjectName(ManagementFactory.OPERATING_SYSTEM_MXBEAN_NAME),"ProcessCpuTime");}
        catch(JMException unavailable){throw new IllegalStateException("Process CPU time is unavailable",unavailable);}
    }
    void begin(String next){if(next.equals("building")&&Boolean.getBoolean("iaa.mpRoofJobs"))startRoofJobs();stage=next;ticks=0;stageAt=System.nanoTime();timings.clear();phaseCpu=threads.getThreadCpuTime(serverThread);phaseWorker=workerCpu();phaseProcess=processCpu();phaseIn=wire(true);phaseOut=wire(false);phaseRoof=zone.moddev.mc.ironagearchitecture.roof.RoofNetwork.encodedBytes.get();for(int id:players.keySet())command(id,"phase:"+stage,BlockPos.ORIGIN,"");System.out.println("IAA_MP_STAGE "+stage);MPFiles.write(root.resolve("progress.json"),Collections.singletonMap("stage",stage));}
    void end(){if(timings.isEmpty())return;Collections.sort(timings);long now=System.nanoTime();Map<String,Object> row=new LinkedHashMap<>();row.put("stage",stage.equals("verify")?"verify-"+verifyFor:stage);row.put("seconds",(now-stageAt)/1e9);row.put("ticks",timings.size());row.put("tps",Math.min(20,timings.size()/((now-stageAt)/1e9)));double total=0;for(double n:timings)total+=n;row.put("meanMs",total/timings.size());row.put("p95Ms",percent(timings,95));row.put("p99Ms",percent(timings,99));row.put("maxMs",percent(timings,100));row.put("mainCpuMs",(threads.getThreadCpuTime(serverThread)-phaseCpu)/1e6);row.put("observedWorkerCpuMs",Math.max(0,workerCpu()-phaseWorker)/1e6);row.put("processCpuMs",(processCpu()-phaseProcess)/1e6);row.put("inboundBytes",wire(true)-phaseIn);row.put("outboundBytes",wire(false)-phaseOut);row.put("roofPayloadBytes",zone.moddev.mc.ironagearchitecture.roof.RoofNetwork.encodedBytes.get()-phaseRoof);row.put("loadedChunks",world.getChunkProvider().getLoadedChunkCount());row.put("heapUsedMiB",(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory())/1048576.0);rows.add(row);MPFiles.write(root.resolve("stages.json"),rows);}
    static double percent(List<Double> data,int n){return data.get((data.size()-1)*n/100);}
    @SubscribeEvent(priority=EventPriority.HIGHEST) public void before(TickEvent.ServerTickEvent e){if(e.phase==TickEvent.Phase.START){before=System.nanoTime();tickUptime=ManagementFactory.getRuntimeMXBean().getUptime();tickCpu=threads.getThreadCpuTime(serverThread);tickGc=gcMillis();measuredStage=stage;}}
    @SubscribeEvent(priority=EventPriority.LOWEST) public void after(TickEvent.ServerTickEvent e){if(e.phase!=TickEvent.Phase.END||finished)return;try{advance();}catch(Throwable error){error.printStackTrace();fail(error.toString());}}
    void advance()throws Exception{
        if(stage.equals(measuredStage)&&!stage.equals("waiting")&&!stage.equals("preparing")){double ms=(System.nanoTime()-before)/1e6;timings.add(ms);if(ms>=25){Map<String,Object> slow=new LinkedHashMap<>();slow.put("stage",stage);slow.put("uptimeMs",tickUptime);slow.put("durationMs",ms);slow.put("gcMs",Math.max(0,gcMillis()-tickGc));slow.put("cpuMs",(threads.getThreadCpuTime(serverThread)-tickCpu)/1e6);slowTicks.add(slow);}}ticks++;
        if(System.nanoTime()-started>900000000000L){fail("Case exceeded 15 minutes");return;}
        if(prepare){if(!pending())quiet++;else quiet=0;if(quiet>30){server.saveAllWorlds(false);MPFiles.write(root.resolve("prepared.json"),Collections.singletonMap("passed",true));finished=true;server.initiateShutdown();}return;}
        if(stage.equals("waiting")){if(Files.exists(root.resolve("connect.flag")))begin("join");return;}
        if(stage.equals("join")||stage.equals("reconnect")){if(ready.size()==expected&&players.size()==expected&&!pending()){if(++quiet>=20){end();verify(reconnectRound==0?"join":"reconnect-"+reconnectRound);}}else quiet=0;return;}
        if(stage.equals("idle")&&ticks>=400){end();begin("building");for(int id:players.keySet()){move(id,MPPlan.plot(id,spread),"building");command(id,"build",MPPlan.plot(id,spread),"");}return;}
        if(stage.equals("building")&&built.size()==expected){end();validateMaterials();begin("settling");return;}
        if(stage.equals("settling")&&!pending()){end();validateShapes();verify("building");return;}
        if(stage.equals("travel")&&!pending()&&ticks>40){end();verify("travel");return;}
        if(stage.equals("return")&&!pending()&&ticks>40){end();verify("return");return;}
        if(stage.equals("verify")){for(int id:players.keySet()){if(!fingerprints.containsKey(id)){EntityPlayerMP p=players.get(id);fingerprints.put(id,MPFingerprint.submit(MPFingerprint.capture(world,((int)Math.floor(p.posX))>>4,((int)Math.floor(p.posZ))>>4)));}Future<MPFingerprint.Result> future=fingerprints.get(id);if(future.isDone()&&requested.add(id)){MPFingerprint.Result result=future.get();EntityPlayerMP p=players.get(id);command(id,"verify:"+verifyFor,new BlockPos(((int)Math.floor(p.posX))>>4,0,((int)Math.floor(p.posZ))>>4),result.hash);}}
            if(verified.size()==expected){end();Map<String,Object> proof=new LinkedHashMap<>();proof.put("stage",verifyFor);proof.put("allClients",expected);proof.put("sequence",sequence);proof.put("elapsedSeconds",(System.nanoTime()-stageAt)/1e9);MPFiles.write(root.resolve("verified-"+verifyFor+".json"),proof);if(verifyFor.equals("join")){begin("idle");}else if(verifyFor.equals("building")){begin("travel");for(int id:players.keySet())move(id,MPPlan.destination(id,spread),"travel");}else if(verifyFor.equals("travel")){begin("return");for(int id:players.keySet())move(id,MPPlan.plot(id,spread),"return");}else if(reconnectRound<reconnects){reconnect();}else finish();return;}}
        if((System.nanoTime()-stageAt)>180000000000L){fail("Stage timed out: "+stage+" ready="+ready+" built="+built+" verified="+verified+" requested="+requested);}
    }
    void reconnect(){reconnectRound++;begin("reconnect");for(int id:new ArrayList<>(players.keySet()))command(id,"reconnect",MPPlan.plot(id,spread),"");players.clear();ready.clear();verified.clear();quiet=0;}
    void verify(String previous){verifyFor=previous;sequence++;begin("verify");fingerprints.clear();requested.clear();verified.clear();System.out.println("IAA_MP_VERIFY "+previous+" sequence="+sequence);}
    void validateMaterials(){for(int id:players.keySet())for(Map.Entry<BlockPos,Block> entry:MPPlan.finalBlocks(id,MPPlan.plot(id,spread)).entrySet())if(world.getBlockState(entry.getKey()).getBlock()!=entry.getValue())throw new IllegalStateException("Server missing built block at "+entry.getKey()+" id="+id);}
    void validateShapes(){validateMaterials();for(int id:players.keySet())for(MPPlan.Op op:MPPlan.steps(MPPlan.plot(id,spread)))if(op.roof&&!op.remove&&!SmartThatchBlock.owner(world.getBlockState(op.at)))throw new IllegalStateException("Roof did not shape at "+op.at);}
    void finish(){validateShapes();for(zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk d:roofJobs){if(d.active||d.index!=d.operations.size()||d.index==0)throw new IllegalStateException("Unfinished multiplayer roof job");for(Map.Entry<Long,zone.moddev.mc.ironagearchitecture.roof.RoofCell> e:d.drawing.cells.entrySet())if(!e.getValue().equals(zone.moddev.mc.ironagearchitecture.roof.RoofData.get(world).at(world,BlockPos.fromLong(e.getKey()))))throw new IllegalStateException("Multiplayer frame missing");}Map<String,Object> designed=new LinkedHashMap<>();for(zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk d:roofJobs)for(long key:d.drawing.cells.keySet()){BlockPos pos=BlockPos.fromLong(key);net.minecraft.block.state.IBlockState state=world.getBlockState(pos);designed.put(pos.getX()+","+pos.getY()+","+pos.getZ(),Arrays.asList(state.getBlock().getRegistryName().toString(),state.getBlock().getMetaFromState(state)));}MPFiles.write(root.resolve("roof-design-cells.json"),designed);stage="reporting";long start=System.nanoTime();server.saveAllWorlds(false);double saveMs=(System.nanoTime()-start)/1e6;System.gc();Map<String,Object> result=new LinkedHashMap<>();result.put("passed",true);boolean performance=true;for(Map<String,Object> row:rows)if(row.get("stage").equals("idle")||row.get("stage").equals("building"))performance&=((Number)row.get("p95Ms")).doubleValue()<50&&((Number)row.get("tps")).doubleValue()>=19;result.put("steadyPerformanceTargetMet",performance);result.put("clients",expected);result.put("spread",spread);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));result.put("headless",System.getProperty("java.awt.headless"));result.put("processors",Runtime.getRuntime().availableProcessors());result.put("heapLimitMiB",Runtime.getRuntime().maxMemory()/1048576);result.put("heapAfterGcMiB",(Runtime.getRuntime().totalMemory()-Runtime.getRuntime().freeMemory())/1048576);result.put("saveMs",saveMs);result.put("operationsPerClient",91);result.put("concurrentWorkbenchJobs",roofJobs.size());result.put("clientClipboardDesign",Boolean.getBoolean("iaa.mpRoofDesign"));result.put("roofConstructionMaxMs",zone.moddev.mc.ironagearchitecture.roof.RoofConstruction.maxWorkNanos/1e6);result.put("phases",rows);result.put("networkThreadsOverride",System.getProperty("io.netty.eventLoopThreads","default"));result.put("handshakeGuards",players.values().stream().filter(p->p.connection.netManager.channel().pipeline().get("iaa_handshake_guard")!=null).count());result.put("reconnectRounds",reconnectRound);result.put("allTcp",meters.values().stream().allMatch(m->m.tcp));MPFiles.write(root.resolve("slow-ticks.json"),slowTicks);MPFiles.write(root.resolve("server-result.json"),result);for(int id:players.keySet())command(id,"stop",BlockPos.ORIGIN,"");finished=true;new Thread(()->{try{Thread.sleep(3000);}catch(InterruptedException ignored){}server.initiateShutdown();},"MP test shutdown").start();System.out.println("IAA_MP_SERVER_PASS");}
    void startRoofJobs(){for(int id:players.keySet()){BlockPos p=MPPlan.plot(id,spread).add(1,20,1);for(int x=0;x<4;x++)for(int z=0;z<4;z++)world.setBlockState(p.add(x,0,z),zone.moddev.mc.ironagearchitecture.ArchitectureBlocks.findFloor("oak",FloorShape.FULL,null).getDefaultState(),2);BlockPos at=p.add(2,1,2);world.setBlockState(at,zone.moddev.mc.ironagearchitecture.ArchitectureBlocks.ARCHITECTS_WORKBENCH.getDefaultState(),3);zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk d=(zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk)world.getTileEntity(at);zone.moddev.mc.ironagearchitecture.roof.RoofConstruction.detect(d);if(Boolean.getBoolean("iaa.mpRoofDesign")){net.minecraft.item.ItemStack board=new net.minecraft.item.ItemStack(zone.moddev.mc.ironagearchitecture.ArchitectureBlocks.ROOF_CLIPBOARD);zone.moddev.mc.ironagearchitecture.roof.RoofClipboardItem.bind(board,d.drawing,world.provider.getDimension());players.get(id).inventory.setInventorySlotContents(8,board);players.get(id).inventoryContainer.detectAndSendChanges();command(id,"roof-drawing",at,"");}else if(!zone.moddev.mc.ironagearchitecture.roof.RoofConstruction.start(d,players.get(id)))throw new IllegalStateException(d.status);roofJobs.add(d);}}
    void fail(String reason){if(finished)return;finished=true;Map<String,Object> result=new LinkedHashMap<>();result.put("passed",false);result.put("reason",reason);result.put("stage",stage);result.put("clients",expected);result.put("spread",spread);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));result.put("phases",rows);MPFiles.write(root.resolve("slow-ticks.json"),slowTicks);MPFiles.write(root.resolve("server-result.json"),result);System.err.println("IAA_MP_FAILED "+reason);for(int id:players.keySet())command(id,"stop",BlockPos.ORIGIN,reason);server.saveAllWorlds(false);server.initiateShutdown();}
}
